14: class GameUI {
15:   constructor(g){this.g=g;this.toastTimers=[];this.damageTexts=[];this.panel=null;this.panelRefresh=0;this.regionTimer=0;this.levelTimer=0;this.dialogueStep=0;this.onboarding=true;}
16:   showScreen(id){document.querySelectorAll('.screen').forEach(n=>n.classList.remove('active'));$(id)?.classList.add('active')}
17:   toast(text,bright=false){const node=document.createElement('div');node.className='toast'+(bright?' bright':'');node.textContent=text;$('toast-layer').append(node);setTimeout(()=>node.remove(),3000)}
18:   damageNumber(x,y,value,crit=false){this.damageTexts.push({x,y,text:String(value),life:.8,max:.8,crit,color:crit?'#f2c77f':'#e5ded2'})}
19:   lootToast(item){const node=document.createElement('div');node.className='loot-entry';node.innerHTML=`<span>${esc(item.icon||'✦')}</span> ${esc(item.name)} <b>${esc(item.rarity||'Common')}</b>`;$('loot-log').prepend(node);setTimeout(()=>node.remove(),4600);this.toast(`${item.rarity||'Common'} · ${item.name}`,item.rarity==='Legendary')}
20:   levelUp(){const p=this.g.player;$('lu-level').textContent=p.level;$('levelup-fx').classList.remove('hidden');clearTimeout(this.levelTimer);this.levelTimer=setTimeout(()=>$('levelup-fx').classList.add('hidden'),1800);this.renderPanel()}
21:   onKill(e){this.g.kills++;if(this.g.quest==='intro'&&this.g.kills>=1)this.g.quest='hunt';if(this.g.quest==='hunt'&&this.g.kills>=6)this.g.quest='boss';if(e.type==='boss'){this.g.bossDefeated=true;this.g.quest='done';$('boss-bar').classList.add('hidden');this.toast('The seal answers. The Cinder Warden is defeated.',true)}this.renderPanel()}
22:   showDeath(){this.g.paused=true;$('death-meta').textContent=`Level ${this.g.player.level} · ${this.g.player.gold} gold carried`;$('screen-death').classList.add('active')}
23:   bossPhase(phase){$('boss-phases').querySelectorAll('i').forEach((el,i)=>el.classList.toggle('active',i<phase))}
