const sleep = ms => new Promise(r => setTimeout(r, ms));
const targets = await fetch('http://127.0.0.1:9222/json').then(r => r.json());
const target = targets.find(t => t.type === 'page');
if (!target) throw new Error('No Chrome page target');
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
let id = 0;
const pending = new Map();
const logs = [];
ws.onmessage = event => {
  const msg = JSON.parse(event.data);
  if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); }
  if (msg.method === 'Runtime.exceptionThrown') logs.push({type:'exception',text:msg.params.exceptionDetails.text,detail:msg.params.exceptionDetails.exception?.description});
  if (msg.method === 'Runtime.consoleAPICalled' && msg.params.type === 'error') logs.push({type:'console',text:msg.params.args.map(a=>a.value||a.description).join(' ')});
};
function send(method, params={}) { const n=++id; ws.send(JSON.stringify({id:n,method,params})); return new Promise(resolve=>pending.set(n,resolve)); }
async function evaljs(expression) { const result=await send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true}); if(result.error) throw new Error(JSON.stringify(result.error)); return result.result?.result?.value; }
await send('Runtime.enable'); await send('Page.enable');
await send('Page.navigate',{url:'http://localhost:3002/'}); await sleep(1200);
const results={initial:await evaljs(`({title:document.title,main:document.querySelector('#screen-main').className,continueDisabled:document.querySelector('#btn-continue').disabled,errors:[]})`)};
await evaljs(`document.querySelector('#btn-new').click()`); await sleep(150);
await evaljs(`document.querySelector('.class-card').click(); document.querySelector('#btn-enter-world').click()`); await sleep(150);
await evaljs(`document.querySelector('#btn-skip-intro').click()`); await sleep(700);
results.started=await evaljs(`({hud:!document.querySelector('#hud').classList.contains('hidden'),screen:document.querySelector('#screen-main').className,abilities:document.querySelectorAll('#abilities [data-ability]').length,playerName:document.querySelector('#hud-name').textContent})`);
await evaljs(`document.dispatchEvent(new KeyboardEvent('keydown',{key:'w',bubbles:true}))`); await sleep(1000); await evaljs(`document.dispatchEvent(new KeyboardEvent('keyup',{key:'w',bubbles:true}))`);
await evaljs(`document.dispatchEvent(new KeyboardEvent('keydown',{key:'e',bubbles:true}))`); await sleep(200); await evaljs(`document.querySelector('#dialogue-choices button')?.click()`); await sleep(200);
results.quest=await evaljs(`({title:document.querySelector('#qt-title').textContent,dialogueHidden:document.querySelector('#dialogue-layer').classList.contains('hidden')})`);
await evaljs(`document.dispatchEvent(new KeyboardEvent('keydown',{key:'i',bubbles:true}))`); await sleep(200);
results.inventory=await evaljs(`({open:!document.querySelector('#panel-layer').classList.contains('hidden'),title:document.querySelector('#panel-title').textContent,slots:document.querySelectorAll('[data-slot]').length})`);
await evaljs(`document.querySelector('#panel-close').click(); document.dispatchEvent(new KeyboardEvent('keydown',{key:'m',bubbles:true}))`); await sleep(150);
results.map=await evaljs(`({open:!document.querySelector('#panel-layer').classList.contains('hidden'),canvas:!!document.querySelector('#large-map')})`);
await evaljs(`document.querySelector('#panel-close').click(); document.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',bubbles:true}))`); await sleep(150);
results.pause=await evaljs(`({paused:document.querySelector('#screen-pause').classList.contains('active')})`);
await evaljs(`document.querySelector('#btn-resume').click()`); await sleep(100);
await evaljs(`document.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',bubbles:true})); document.querySelector('#btn-save-quit').click()`); await sleep(250);
results.saved=await evaljs(`({menu:document.querySelector('#screen-main').classList.contains('active'),continueDisabled:document.querySelector('#btn-continue').disabled,meta:document.querySelector('#save-meta').textContent})`);
await evaljs(`document.querySelector('#btn-continue').click()`); await sleep(500);
results.continue=await evaljs(`({hud:!document.querySelector('#hud').classList.contains('hidden'),name:document.querySelector('#hud-name').textContent,quest:document.querySelector('#qt-title').textContent})`);
await sleep(250);
const shot=await send('Page.captureScreenshot',{format:'jpeg',quality:90,clip:{x:0,y:0,width:1280,height:720,scale:1}});
if(shot.result?.data) await (await import('node:fs/promises')).writeFile('/tmp/opencode/eldoria-final.jpg',Buffer.from(shot.result.data,'base64'));
results.logs=logs;
console.log(JSON.stringify(results,null,2));
ws.close();

